  "konto.seite.schritt3": "Se non fai ancora parte di nessun club, lo stesso pulsante si trova direttamente nella schermata in cui arrivi dopo l'accesso — nella schermata di avviso, nella ricerca dei club o in «I tuoi club».",
  "konto.seite.schritt4": "Conferma l'eliminazione definitiva. Il tuo account, i tuoi profili nei club e i tuoi contenuti personali verranno eliminati in modo irreversibile.",
  "konto.seite.wartend": "Se la tua ammissione è ancora in attesa dell'approvazione del club, trovi la funzione di eliminazione nella schermata di avviso subito dopo l'accesso.",
  "konto.seite.kostenTitel": "Sui costi:",
  "konto.seite.kostenText": "Per te come membro non ce ne sono. Non esiste un abbonamento personale che termini o continui con il tuo account — l'accesso è pagato dal club, e il contratto è tra noi e il club.",
  "konto.seite.ohneAnmeldung": "Se non riesci più ad accedere (ad es. perché non hai più accesso al tuo indirizzo e-mail), scrivici a {email}. Verificheremo la tua identità ed elimineremo il tuo account manualmente.",
  "konto.seite.datenTitel": "Quali dati vengono eliminati",
  "konto.seite.datenText": "Con l'eliminazione dell'account rimuoviamo definitivamente: il tuo accesso e la tua password, i dati anagrafici (nome, contatti, data di nascita, indirizzo), le assegnazioni a club e squadre, i collegamenti familiari, i messaggi e le risposte ai sondaggi che hai scritto, oltre alla tua registrazione per le notifiche push.",
  "konto.seite.newsText": "Le news che hai scritto per il tuo club restano al club. Il tuo nome viene rimosso; come autore comparirà «Club».",
  "konto.seite.aufbewahrenTitel": "Quali dati conserviamo per motivi legali",
  "konto.seite.aufbewahrenText": "A causa degli obblighi di conservazione previsti dal diritto commerciale e fiscale tedesco (tra cui § 147 AO, § 257 HGB), dobbiamo conservare le fatture emesse ai club e i relativi dati di pagamento fino a dieci anni. Questi dati vengono trattati esclusivamente per le finalità previste dalla legge e poi eliminati.",
  "konto.seite.details": "Trovi i dettagli nella nostra {link}.",
  "konto.seite.zeitTitel": "Tempistiche",
  "konto.seite.zeitText": "L'eliminazione tramite l'app avviene immediatamente. Gestiamo le richieste di eliminazione via e-mail entro 30 giorni.",
